  // --- Living Fractals & Biomorphic Procedural Geometry Helpers ---
  function mergeBufferGeometries(geometries) {
    let totalVerts = 0;
    geometries.forEach(g => { totalVerts += g.attributes.position.count; });
    const positions = new Float32Array(totalVerts * 3);
    const indices = [];
    let vOffset = 0;
    geometries.forEach(g => {
      const p = g.attributes.position.array;
      positions.set(p, vOffset * 3);
      if (g.index) {
        const idx = g.index.array;
        for (let i = 0; i < idx.length; i++) indices.push(idx[i] + vOffset);
      } else {
        for (let i = 0; i < g.attributes.position.count; i++) indices.push(i + vOffset);
      }
      vOffset += g.attributes.position.count;
    });
    const merged = new THREE.BufferGeometry();
    merged.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    merged.setIndex(indices);
    merged.computeVertexNormals();
    return merged;
  }

  function createMobiusGeometry(radius = 22, width = 9.5, uSegments = 64, vSegments = 16) {
    const geom = new THREE.BufferGeometry();
    const positions = [];
    const indices = [];
    for (let i = 0; i <= uSegments; i++) {
      const u = (i / uSegments) * Math.PI * 2;
      for (let j = 0; j <= vSegments; j++) {
        const v = ((j / vSegments) - 0.5) * width;
        const x = (radius + v * Math.cos(u / 2)) * Math.cos(u);
        const y = (radius + v * Math.cos(u / 2)) * Math.sin(u);
        const z = v * Math.sin(u / 2);
        positions.push(x, y, z);
      }
    }
    const stride = vSegments + 1;
    for (let i = 0; i < uSegments; i++) {
      for (let j = 0; j < vSegments; j++) {
        const a = i * stride + j;
        const b = (i + 1) * stride + j;
        const c = (i + 1) * stride + (j + 1);
        const d = i * stride + (j + 1);
        indices.push(a, b, d, b, c, d);
      }
    }
    geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geom.setIndex(indices);
    geom.computeVertexNormals();
    geom.center();
    return geom;
  }

  function createKleinBottleGeometry(uSeg = 48, vSeg = 24) {
    const geom = new THREE.BufferGeometry();
    const positions = [];
    const indices = [];
    const r0 = 15;
    for (let i = 0; i <= uSeg; i++) {
      const u = (i / uSeg) * Math.PI * 2;
      const cosU = Math.cos(u), sinU = Math.sin(u);
      const cosU2 = Math.cos(u / 2), sinU2 = Math.sin(u / 2);
      for (let j = 0; j <= vSeg; j++) {
        const v = (j / vSeg) * Math.PI * 2;
        const sinV = Math.sin(v), sin2V = Math.sin(2 * v);
        const rad = r0 + 6.5 * (cosU2 * sinV - sinU2 * sin2V);
        const x = rad * cosU;
        const y = rad * sinU;
        const z = 7.5 * (sinU2 * sinV + cosU2 * sin2V);
        positions.push(x, y, z);
      }
    }
    const stride = vSeg + 1;
    for (let i = 0; i < uSeg; i++) {
      for (let j = 0; j < vSeg; j++) {
        const a = i * stride + j;
        const b = (i + 1) * stride + j;
        const c = (i + 1) * stride + (j + 1);
        const d = i * stride + (j + 1);
        indices.push(a, b, d, b, c, d);
      }
    }
    geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geom.setIndex(indices);
    return geom;
  }

  function createCalabiYauGeometry(uSeg = 48, vSeg = 24) {
    const geom = new THREE.BufferGeometry();
    const positions = [];
    const indices = [];
    const n = 5;
    for (let i = 0; i <= uSeg; i++) {
      const u = (i / uSeg) * Math.PI * 2 - Math.PI;
      for (let j = 0; j <= vSeg; j++) {
        const v = (j / vSeg) * Math.PI * 2 - Math.PI;
        const r = 13 + 4.5 * Math.cos(n * u) * Math.sin(n * v);
        const x = r * Math.sin(u) * Math.cos(v);
        const y = r * Math.sin(u) * Math.sin(v) + 3.8 * Math.sin(n * u);
        const z = r * Math.cos(u) + 3.8 * Math.cos(n * v);
        positions.push(x, y, z);
      }
    }
    const stride = vSeg + 1;
    for (let i = 0; i < uSeg; i++) {
      for (let j = 0; j < vSeg; j++) {
        const a = i * stride + j;
        const b = (i + 1) * stride + j;
        const c = (i + 1) * stride + (j + 1);
        const d = i * stride + (j + 1);
        indices.push(a, b, d, b, c, d);
      }
    }
    geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geom.setIndex(indices);
    return geom;
  }

  function createSuperformulaGeometry(uSeg = 36, vSeg = 36) {
    const geom = new THREE.BufferGeometry();
    const positions = [];
    const indices = [];
    function sf(phi, m, n1, n2, n3) {
      const t1 = Math.pow(Math.abs(Math.cos(m * phi / 4)), n2);
      const t2 = Math.pow(Math.abs(Math.sin(m * phi / 4)), n3);
      const r = Math.pow(t1 + t2, -1 / n1);
      return isFinite(r) ? r : 1;
    }
    for (let i = 0; i <= uSeg; i++) {
      const u = (i / uSeg) * Math.PI - Math.PI / 2;
      const r1 = sf(u, 6, 1.2, 4, 4);
      for (let j = 0; j <= vSeg; j++) {
        const v = (j / vSeg) * Math.PI * 2 - Math.PI;
        const r2 = sf(v, 6, 1.2, 4, 4);
        const rad = 13 * r1 * r2;
        const x = rad * Math.cos(u) * Math.cos(v);
        const y = rad * Math.cos(u) * Math.sin(v);
        const z = rad * Math.sin(u);
        positions.push(x, y, z);
      }
    }
    const stride = vSeg + 1;
    for (let i = 0; i < uSeg; i++) {
      for (let j = 0; j < vSeg; j++) {
        const a = i * stride + j;
        const b = (i + 1) * stride + j;
        const c = (i + 1) * stride + (j + 1);
        const d = i * stride + (j + 1);
        indices.push(a, b, d, b, c, d);
      }
    }
    geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geom.setIndex(indices);
    return geom;
  }

  function createBesselFlowerGeometry(radialSegs = 24, circSegs = 40) {
    const geom = new THREE.BufferGeometry();
    const positions = [];
    const indices = [];
    const maxR = 22;
    for (let i = 0; i <= radialSegs; i++) {
      const rNorm = i / radialSegs;
      const r = rNorm * maxR;
      for (let j = 0; j <= circSegs; j++) {
        const theta = (j / circSegs) * Math.PI * 2;
        const petals = Math.sin(5 * theta);
        const wave = Math.sin(rNorm * Math.PI * 3.2) * (1 - rNorm * 0.25);
        const cup = Math.pow(rNorm, 2.0) * 10;
        const z = cup + wave * 4.2 * petals;
        const x = r * Math.cos(theta);
        const y = r * Math.sin(theta);
        positions.push(x, y, z);
      }
    }
    const stride = circSegs + 1;
    for (let i = 0; i < radialSegs; i++) {
      for (let j = 0; j < circSegs; j++) {
        const a = i * stride + j;
        const b = (i + 1) * stride + j;
        const c = (i + 1) * stride + (j + 1);
        const d = i * stride + (j + 1);
        indices.push(a, b, d, b, c, d);
      }
    }
    geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geom.setIndex(indices);
    return geom;
  }

  function createDiniSurfaceGeometry(uSeg = 30, vSeg = 36) {
    const geom = new THREE.BufferGeometry();
    const positions = [];
    const indices = [];
    const a = 13.0, b = 2.2;
    for (let i = 0; i <= uSeg; i++) {
      const u = 0.15 + (i / uSeg) * 1.85;
      const sinU = Math.sin(u), cosU = Math.cos(u);
      const logTan = Math.log(Math.tan(u / 2));
      for (let j = 0; j <= vSeg; j++) {
        const v = (j / vSeg) * Math.PI * 3.5;
        const x = a * sinU * Math.cos(v);
        const y = a * sinU * Math.sin(v);
        const z = a * (cosU + logTan) + b * v;
        positions.push(x, y, z);
      }
    }
    const stride = vSeg + 1;
    for (let i = 0; i < uSeg; i++) {
      for (let j = 0; j < vSeg; j++) {
        const a_idx = i * stride + j;
        const b_idx = (i + 1) * stride + j;
        const c_idx = (i + 1) * stride + (j + 1);
        const d_idx = i * stride + (j + 1);
        indices.push(a_idx, b_idx, d_idx, b_idx, c_idx, d_idx);
      }
    }
    geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geom.setIndex(indices);
    return geom;
  }

  function createEnneperGeometry(uSeg = 32, vSeg = 32) {
    const geom = new THREE.BufferGeometry();
    const positions = [];
    const indices = [];
    const maxU = 1.6;
    for (let i = 0; i <= uSeg; i++) {
      const u = -maxU + (i / uSeg) * (2 * maxU);
      for (let j = 0; j <= vSeg; j++) {
        const v = -maxU + (j / vSeg) * (2 * maxU);
        const x = (u - (u * u * u) / 3 + u * v * v) * 8.0;
        const y = (v - (v * v * v) / 3 + v * u * u) * 8.0;
        const z = (u * u - v * v) * 8.0;
        positions.push(x, y, z);
      }
    }
    const stride = vSeg + 1;
    for (let i = 0; i < uSeg; i++) {
      for (let j = 0; j < vSeg; j++) {
        const a = i * stride + j;
        const b = (i + 1) * stride + j;
        const c = (i + 1) * stride + (j + 1);
        const d = i * stride + (j + 1);
        indices.push(a, b, d, b, c, d);
      }
    }
    geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geom.setIndex(indices);
    return geom;
  }

  function createStellatedCoreGeometry() {
    const base = new THREE.IcosahedronGeometry(12, 1);
    const pos = base.attributes.position;
    const count = pos.count;
    const positions = [];
    const indices = [];
    for (let i = 0; i < count; i += 3) {
      const v1 = new THREE.Vector3().fromBufferAttribute(pos, i);
      const v2 = new THREE.Vector3().fromBufferAttribute(pos, i + 1);
      const v3 = new THREE.Vector3().fromBufferAttribute(pos, i + 2);
      const apex = new THREE.Vector3().add(v1).add(v2).add(v3).divideScalar(3).normalize().multiplyScalar(24);
      const baseIdx = positions.length / 3;
      positions.push(v1.x, v1.y, v1.z, v2.x, v2.y, v2.z, v3.x, v3.y, v3.z, apex.x, apex.y, apex.z);
      indices.push(baseIdx, baseIdx + 1, baseIdx + 3);
      indices.push(baseIdx + 1, baseIdx + 2, baseIdx + 3);
      indices.push(baseIdx + 2, baseIdx, baseIdx + 3);
    }
    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geom.setIndex(indices);
    return geom;
  }

  // --- Living Fractals & Biomorphic Sculptures Geometry Generator (18 Models) ---
  function generateFractalGeometry(preset, complexity, scale) {
    const comp = parseInt(complexity, 10) || 64;
    let geom = null;

    if (preset === 'gyroid') {
      const detail = Math.min(5, Math.max(3, Math.floor(comp / 16)));
      geom = new THREE.IcosahedronGeometry(18, detail);
      const pos = geom.attributes.position;
      const v = new THREE.Vector3();
      for (let i = 0; i < pos.count; i++) {
        v.fromBufferAttribute(pos, i);
        const k = 0.22;
        const gyr = Math.sin(k * v.x) * Math.cos(k * v.y) +
                    Math.sin(k * v.y) * Math.cos(k * v.z) +
                    Math.sin(k * v.z) * Math.cos(k * v.x);
        v.normalize().multiplyScalar(18 + gyr * 4.2);
        pos.setXYZ(i, v.x, v.y, v.z);
      }
    } else if (preset === 'mobius') {
      geom = createMobiusGeometry(22, 9.5, comp, Math.max(14, Math.floor(comp / 4)));
    } else if (preset === 'klein_bottle') {
      geom = createKleinBottleGeometry(Math.max(28, comp), Math.max(14, Math.floor(comp / 3)));
    } else if (preset === 'calabi_yau') {
      geom = createCalabiYauGeometry(Math.max(28, comp), Math.max(16, Math.floor(comp / 3)));
    } else if (preset === 'lorenz') {
      const pts = [];
      let x = 0.1, y = 0, z = 0;
      const dt = 0.012, sigma = 10, rho = 28, beta = 8 / 3;
      const steps = Math.min(500, Math.max(180, comp * 4));
      for (let i = 0; i < steps; i++) {
        const dx = sigma * (y - x) * dt;
        const dy = (x * (rho - z) - y) * dt;
        const dz = (x * y - beta * z) * dt;
        x += dx; y += dy; z += dz;
        pts.push(new THREE.Vector3(x, y, z - 25));
      }
      const curve = new THREE.CatmullRomCurve3(pts, false);
      geom = new THREE.TubeGeometry(curve, steps, 2.2, 12, false);
    } else if (preset === 'aizawa') {
      const pts = [];
      let x = 0.1, y = 0, z = 0;
      const a = 0.95, b = 0.7, c = 0.6, d = 3.5, e = 0.25, f = 0.1;
      const dt = 0.014;
      const steps = Math.min(500, Math.max(200, comp * 4));
      for (let i = 0; i < steps; i++) {
        const dx = ((z - b) * x - d * y) * dt;
        const dy = (d * x + (z - b) * y) * dt;
        const dz = (c + a * z - (z * z * z) / 3 - (x * x + y * y) * (1 + e * z) + f * z * (x * x * x)) * dt;
        x += dx; y += dy; z += dz;
        pts.push(new THREE.Vector3(x * 15, y * 15, (z - 0.7) * 15));
      }
      const curve = new THREE.CatmullRomCurve3(pts, false);
      geom = new THREE.TubeGeometry(curve, steps, 2.0, 10, false);
    } else if (preset === 'chua_circuit') {
      const pts = [];
      let x = 0.1, y = 0, z = 0;
      const alpha = 15.6, beta = 28, m0 = -1.143, m1 = -0.714;
      const dt = 0.008;
      const steps = Math.min(500, Math.max(200, comp * 4));
      for (let i = 0; i < steps; i++) {
        const h = m1 * x + 0.5 * (m0 - m1) * (Math.abs(x + 1) - Math.abs(x - 1));
        const dx = alpha * (y - x - h) * dt;
        const dy = (x - y + z) * dt;
        const dz = (-beta * y) * dt;
        x += dx; y += dy; z += dz;
        pts.push(new THREE.Vector3(x * 6.5, y * 6.5, z * 6.5));
      }
      const curve = new THREE.CatmullRomCurve3(pts, false);
      geom = new THREE.TubeGeometry(curve, steps, 2.2, 10, false);
    } else if (preset === 'biomorph') {
      const detail = Math.min(5, Math.max(3, Math.floor(comp / 15)));
      geom = new THREE.IcosahedronGeometry(16, detail);
      const pos = geom.attributes.position;
      const v = new THREE.Vector3();
      for (let i = 0; i < pos.count; i++) {
        v.fromBufferAttribute(pos, i);
        const theta = Math.atan2(v.y, v.x);
        const phi = Math.acos(v.z / v.length());
        const r1 = Math.sin(theta * 3.0) * Math.cos(phi * 2.0) * 5.0;
        const r2 = Math.cos(theta * 5.0 + phi * 3.0) * 3.0;
        const r3 = Math.sin(phi * 6.0) * 2.5;
        v.normalize().multiplyScalar(15 + r1 + r2 + r3);
        pos.setXYZ(i, v.x, v.y, v.z);
      }
    } else if (preset === 'superformula') {
      geom = createSuperformulaGeometry(Math.max(24, Math.floor(comp * 0.75)), Math.max(24, Math.floor(comp * 0.75)));
    } else if (preset === 'bessel_flower') {
      geom = createBesselFlowerGeometry(Math.max(20, Math.floor(comp * 0.5)), Math.max(30, Math.floor(comp * 0.8)));
    } else if (preset === 'coral_reef') {
      const branches = 5;
      const groupGeoms = [];
      const steps = Math.min(80, Math.max(35, Math.floor(comp / 2)));
      for (let b = 0; b < branches; b++) {
        const angle = (b / branches) * Math.PI * 2;
        const pts = [];
        const height = 34;
        for (let s = 0; s <= steps; s++) {
          const t = s / steps;
          const flare = Math.sin(t * Math.PI * 0.5) * 15;
          const px = Math.cos(angle + t * 0.7) * flare;
          const py = (t - 0.5) * height;
          const pz = Math.sin(angle + t * 0.7) * flare;
          const ripple = Math.sin(t * 10 + b) * 1.5;
          pts.push(new THREE.Vector3(px + ripple, py, pz));
        }
        const curve = new THREE.CatmullRomCurve3(pts);
        groupGeoms.push(new THREE.TubeGeometry(curve, steps, 2.4, 8, false));
      }
      groupGeoms.push(new THREE.IcosahedronGeometry(8, 2));
      geom = mergeBufferGeometries(groupGeoms);
    } else if (preset === 'supertorus') {
      geom = new THREE.TorusKnotGeometry(16, 4.5, comp * 3, Math.max(12, Math.floor(comp / 4)), 3, 7);
    } else if (preset === 'trefoil_ring') {
      const pts = [];
      const steps = Math.min(300, Math.max(140, comp * 3));
      for (let i = 0; i <= steps; i++) {
        const t = (i / steps) * Math.PI * 2;
        const x = (Math.sin(t) + 2 * Math.sin(2 * t)) * 8.2;
        const y = (Math.cos(t) - 2 * Math.cos(2 * t)) * 8.2;
        const z = (-Math.sin(3 * t)) * 8.2;
        pts.push(new THREE.Vector3(x, y, z));
      }
      const curve = new THREE.CatmullRomCurve3(pts, true);
      geom = new THREE.TubeGeometry(curve, steps, 3.2, 12, true);
    } else if (preset === 'helix') {
      const totalPts = Math.min(300, Math.max(120, comp * 3));
      const pts = [];
      const turns = 3.5;
      const height = 44;
      const r = 13;
      for (let i = 0; i <= totalPts; i++) {
        const t = (i / totalPts);
        const angle = t * Math.PI * 2 * turns;
        const py = (t - 0.5) * height;
        const px = Math.cos(angle) * r;
        const pz = Math.sin(angle) * r;
        pts.push(new THREE.Vector3(px, py, pz));
      }
      const curve = new THREE.CatmullRomCurve3(pts);
      geom = new THREE.TubeGeometry(curve, totalPts, 2.6, 14, false);
    } else if (preset === 'quad_helix') {
      const geoms = [];
      const strands = 4;
      const turns = 2.8;
      const height = 44;
      const steps = Math.min(180, Math.max(80, comp * 2));
      for (let s = 0; s < strands; s++) {
        const phase = (s / strands) * Math.PI * 2;
        const pts = [];
        for (let i = 0; i <= steps; i++) {
          const t = i / steps;
          const angle = t * Math.PI * 2 * turns + phase;
          const r = 13.5;
          pts.push(new THREE.Vector3(Math.cos(angle) * r, (t - 0.5) * height, Math.sin(angle) * r));
        }
        const curve = new THREE.CatmullRomCurve3(pts);
        geoms.push(new THREE.TubeGeometry(curve, steps, 1.8, 8, false));
      }
      const rungs = 7;
      for (let r = 0; r < rungs; r++) {
        const t = (r + 0.5) / rungs;
        const y = (t - 0.5) * height;
        const angle = t * Math.PI * 2 * turns;
        const p1 = new THREE.Vector3(Math.cos(angle) * 13.5, y, Math.sin(angle) * 13.5);
        const p2 = new THREE.Vector3(Math.cos(angle + Math.PI) * 13.5, y, Math.sin(angle + Math.PI) * 13.5);
        const bridgeCurve = new THREE.LineCurve3(p1, p2);
        geoms.push(new THREE.TubeGeometry(bridgeCurve, 8, 1.3, 6, false));
      }
      geom = mergeBufferGeometries(geoms);
    } else if (preset === 'dini_surface') {
      geom = createDiniSurfaceGeometry(Math.max(22, Math.floor(comp * 0.6)), Math.max(26, Math.floor(comp * 0.7)));
    } else if (preset === 'enneper') {
      geom = createEnneperGeometry(Math.max(24, Math.floor(comp * 0.7)), Math.max(24, Math.floor(comp * 0.7)));
    } else if (preset === 'stellated_core') {
      geom = createStellatedCoreGeometry();
    } else {
      geom = new THREE.TorusKnotGeometry(16, 4.5, 96, 24, 2, 3);
    }

    geom.computeBoundingBox();
    geom.center();
    geom.computeVertexNormals();

    const s = parseFloat(scale) || 1.0;
    if (s !== 1.0) geom.scale(s, s, s);
    return geom;
  }

  // Helper string bundle for Standalone HTML export & Three.js code copying
  function getFractalCodeBundle() {
    return `
    function mergeBufferGeometries(geometries) {
      let totalVerts = 0;
      geometries.forEach(g => { totalVerts += g.attributes.position.count; });
      const positions = new Float32Array(totalVerts * 3);
      const indices = [];
      let vOffset = 0;
      geometries.forEach(g => {
        const p = g.attributes.position.array;
        positions.set(p, vOffset * 3);
        if (g.index) {
          const idx = g.index.array;
          for (let i = 0; i < idx.length; i++) indices.push(idx[i] + vOffset);
        } else {
          for (let i = 0; i < g.attributes.position.count; i++) indices.push(i + vOffset);
        }
        vOffset += g.attributes.position.count;
      });
      const merged = new THREE.BufferGeometry();
      merged.setAttribute('position', new THREE.BufferAttribute(positions, 3));
      merged.setIndex(indices);
      merged.computeVertexNormals();
      return merged;
    }

    function createMobiusGeometry(radius, width, uSegments, vSegments) {
      radius = radius || 22; width = width || 9.5; uSegments = uSegments || 64; vSegments = vSegments || 16;
      const geom = new THREE.BufferGeometry();
      const positions = [];
      const indices = [];
      for (let i = 0; i <= uSegments; i++) {
        const u = (i / uSegments) * Math.PI * 2;
        for (let j = 0; j <= vSegments; j++) {
          const v = ((j / vSegments) - 0.5) * width;
          const x = (radius + v * Math.cos(u / 2)) * Math.cos(u);
          const y = (radius + v * Math.cos(u / 2)) * Math.sin(u);
          const z = v * Math.sin(u / 2);
          positions.push(x, y, z);
        }
      }
      const stride = vSegments + 1;
      for (let i = 0; i < uSegments; i++) {
        for (let j = 0; j < vSegments; j++) {
          const a = i * stride + j;
          const b = (i + 1) * stride + j;
          const c = (i + 1) * stride + (j + 1);
          const d = i * stride + (j + 1);
          indices.push(a, b, d, b, c, d);
        }
      }
      geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geom.setIndex(indices);
      return geom;
    }

    function createKleinBottleGeometry(uSeg, vSeg) {
      uSeg = uSeg || 48; vSeg = vSeg || 24;
      const geom = new THREE.BufferGeometry();
      const positions = [];
      const indices = [];
      const r0 = 15;
      for (let i = 0; i <= uSeg; i++) {
        const u = (i / uSeg) * Math.PI * 2;
        const cosU = Math.cos(u), sinU = Math.sin(u);
        const cosU2 = Math.cos(u / 2), sinU2 = Math.sin(u / 2);
        for (let j = 0; j <= vSeg; j++) {
          const v = (j / vSeg) * Math.PI * 2;
          const sinV = Math.sin(v), sin2V = Math.sin(2 * v);
          const rad = r0 + 6.5 * (cosU2 * sinV - sinU2 * sin2V);
          const x = rad * cosU;
          const y = rad * sinU;
          const z = 7.5 * (sinU2 * sinV + cosU2 * sin2V);
          positions.push(x, y, z);
        }
      }
      const stride = vSeg + 1;
      for (let i = 0; i < uSeg; i++) {
        for (let j = 0; j < vSeg; j++) {
          const a = i * stride + j;
          const b = (i + 1) * stride + j;
          const c = (i + 1) * stride + (j + 1);
          const d = i * stride + (j + 1);
          indices.push(a, b, d, b, c, d);
        }
      }
      geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geom.setIndex(indices);
      return geom;
    }

    function createCalabiYauGeometry(uSeg, vSeg) {
      uSeg = uSeg || 48; vSeg = vSeg || 24;
      const geom = new THREE.BufferGeometry();
      const positions = [];
      const indices = [];
      const n = 5;
      for (let i = 0; i <= uSeg; i++) {
        const u = (i / uSeg) * Math.PI * 2 - Math.PI;
        for (let j = 0; j <= vSeg; j++) {
          const v = (j / vSeg) * Math.PI * 2 - Math.PI;
          const r = 13 + 4.5 * Math.cos(n * u) * Math.sin(n * v);
          const x = r * Math.sin(u) * Math.cos(v);
          const y = r * Math.sin(u) * Math.sin(v) + 3.8 * Math.sin(n * u);
          const z = r * Math.cos(u) + 3.8 * Math.cos(n * v);
          positions.push(x, y, z);
        }
      }
      const stride = vSeg + 1;
      for (let i = 0; i < uSeg; i++) {
        for (let j = 0; j < vSeg; j++) {
          const a = i * stride + j;
          const b = (i + 1) * stride + j;
          const c = (i + 1) * stride + (j + 1);
          const d = i * stride + (j + 1);
          indices.push(a, b, d, b, c, d);
        }
      }
      geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geom.setIndex(indices);
      return geom;
    }

    function createSuperformulaGeometry(uSeg, vSeg) {
      uSeg = uSeg || 36; vSeg = vSeg || 36;
      const geom = new THREE.BufferGeometry();
      const positions = [];
      const indices = [];
      function sf(phi, m, n1, n2, n3) {
        const t1 = Math.pow(Math.abs(Math.cos(m * phi / 4)), n2);
        const t2 = Math.pow(Math.abs(Math.sin(m * phi / 4)), n3);
        const r = Math.pow(t1 + t2, -1 / n1);
        return isFinite(r) ? r : 1;
      }
      for (let i = 0; i <= uSeg; i++) {
        const u = (i / uSeg) * Math.PI - Math.PI / 2;
        const r1 = sf(u, 6, 1.2, 4, 4);
        for (let j = 0; j <= vSeg; j++) {
          const v = (j / vSeg) * Math.PI * 2 - Math.PI;
          const r2 = sf(v, 6, 1.2, 4, 4);
          const rad = 13 * r1 * r2;
          const x = rad * Math.cos(u) * Math.cos(v);
          const y = rad * Math.cos(u) * Math.sin(v);
          const z = rad * Math.sin(u);
          positions.push(x, y, z);
        }
      }
      const stride = vSeg + 1;
      for (let i = 0; i < uSeg; i++) {
        for (let j = 0; j < vSeg; j++) {
          const a = i * stride + j;
          const b = (i + 1) * stride + j;
          const c = (i + 1) * stride + (j + 1);
          const d = i * stride + (j + 1);
          indices.push(a, b, d, b, c, d);
        }
      }
      geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geom.setIndex(indices);
      return geom;
    }

    function createBesselFlowerGeometry(radialSegs, circSegs) {
      radialSegs = radialSegs || 24; circSegs = circSegs || 40;
      const geom = new THREE.BufferGeometry();
      const positions = [];
      const indices = [];
      const maxR = 22;
      for (let i = 0; i <= radialSegs; i++) {
        const rNorm = i / radialSegs;
        const r = rNorm * maxR;
        for (let j = 0; j <= circSegs; j++) {
          const theta = (j / circSegs) * Math.PI * 2;
          const petals = Math.sin(5 * theta);
          const wave = Math.sin(rNorm * Math.PI * 3.2) * (1 - rNorm * 0.25);
          const cup = Math.pow(rNorm, 2.0) * 10;
          const z = cup + wave * 4.2 * petals;
          const x = r * Math.cos(theta);
          const y = r * Math.sin(theta);
          positions.push(x, y, z);
        }
      }
      const stride = circSegs + 1;
      for (let i = 0; i < radialSegs; i++) {
        for (let j = 0; j < circSegs; j++) {
          const a = i * stride + j;
          const b = (i + 1) * stride + j;
          const c = (i + 1) * stride + (j + 1);
          const d = i * stride + (j + 1);
          indices.push(a, b, d, b, c, d);
        }
      }
      geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geom.setIndex(indices);
      return geom;
    }

    function createDiniSurfaceGeometry(uSeg, vSeg) {
      uSeg = uSeg || 30; vSeg = vSeg || 36;
      const geom = new THREE.BufferGeometry();
      const positions = [];
      const indices = [];
      const a = 13.0, b = 2.2;
      for (let i = 0; i <= uSeg; i++) {
        const u = 0.15 + (i / uSeg) * 1.85;
        const sinU = Math.sin(u), cosU = Math.cos(u);
        const logTan = Math.log(Math.tan(u / 2));
        for (let j = 0; j <= vSeg; j++) {
          const v = (j / vSeg) * Math.PI * 3.5;
          const x = a * sinU * Math.cos(v);
          const y = a * sinU * Math.sin(v);
          const z = a * (cosU + logTan) + b * v;
          positions.push(x, y, z);
        }
      }
      const stride = vSeg + 1;
      for (let i = 0; i < uSeg; i++) {
        for (let j = 0; j < vSeg; j++) {
          const a_idx = i * stride + j;
          const b_idx = (i + 1) * stride + j;
          const c_idx = (i + 1) * stride + (j + 1);
          const d_idx = i * stride + (j + 1);
          indices.push(a_idx, b_idx, d_idx, b_idx, c_idx, d_idx);
        }
      }
      geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geom.setIndex(indices);
      return geom;
    }

    function createEnneperGeometry(uSeg, vSeg) {
      uSeg = uSeg || 32; vSeg = vSeg || 32;
      const geom = new THREE.BufferGeometry();
      const positions = [];
      const indices = [];
      const maxU = 1.6;
      for (let i = 0; i <= uSeg; i++) {
        const u = -maxU + (i / uSeg) * (2 * maxU);
        for (let j = 0; j <= vSeg; j++) {
          const v = -maxU + (j / vSeg) * (2 * maxU);
          const x = (u - (u * u * u) / 3 + u * v * v) * 8.0;
          const y = (v - (v * v * v) / 3 + v * u * u) * 8.0;
          const z = (u * u - v * v) * 8.0;
          positions.push(x, y, z);
        }
      }
      const stride = vSeg + 1;
      for (let i = 0; i < uSeg; i++) {
        for (let j = 0; j < vSeg; j++) {
          const a = i * stride + j;
          const b = (i + 1) * stride + j;
          const c = (i + 1) * stride + (j + 1);
          const d = i * stride + (j + 1);
          indices.push(a, b, d, b, c, d);
        }
      }
      geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geom.setIndex(indices);
      return geom;
    }

    function createStellatedCoreGeometry() {
      const base = new THREE.IcosahedronGeometry(12, 1);
      const pos = base.attributes.position;
      const count = pos.count;
      const positions = [];
      const indices = [];
      for (let i = 0; i < count; i += 3) {
        const v1 = new THREE.Vector3().fromBufferAttribute(pos, i);
        const v2 = new THREE.Vector3().fromBufferAttribute(pos, i + 1);
        const v3 = new THREE.Vector3().fromBufferAttribute(pos, i + 2);
        const apex = new THREE.Vector3().add(v1).add(v2).add(v3).divideScalar(3).normalize().multiplyScalar(24);
        const baseIdx = positions.length / 3;
        positions.push(v1.x, v1.y, v1.z, v2.x, v2.y, v2.z, v3.x, v3.y, v3.z, apex.x, apex.y, apex.z);
        indices.push(baseIdx, baseIdx + 1, baseIdx + 3);
        indices.push(baseIdx + 1, baseIdx + 2, baseIdx + 3);
        indices.push(baseIdx + 2, baseIdx, baseIdx + 3);
      }
      const geom = new THREE.BufferGeometry();
      geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geom.setIndex(indices);
      return geom;
    }

    function generateFractalGeometry(preset, comp, s) {
      comp = parseInt(comp, 10) || 64;
      let geom = null;
      if (preset === 'gyroid') {
        const detail = Math.min(5, Math.max(3, Math.floor(comp / 16)));
        geom = new THREE.IcosahedronGeometry(18, detail);
        const pos = geom.attributes.position;
        const v = new THREE.Vector3();
        for (let i = 0; i < pos.count; i++) {
          v.fromBufferAttribute(pos, i);
          const k = 0.22;
          const gyr = Math.sin(k * v.x) * Math.cos(k * v.y) + Math.sin(k * v.y) * Math.cos(k * v.z) + Math.sin(k * v.z) * Math.cos(k * v.x);
          v.normalize().multiplyScalar(18 + gyr * 4.2);
          pos.setXYZ(i, v.x, v.y, v.z);
        }
      } else if (preset === 'mobius') {
        geom = createMobiusGeometry(22, 9.5, comp, Math.max(14, Math.floor(comp / 4)));
      } else if (preset === 'klein_bottle') {
        geom = createKleinBottleGeometry(Math.max(28, comp), Math.max(14, Math.floor(comp / 3)));
      } else if (preset === 'calabi_yau') {
        geom = createCalabiYauGeometry(Math.max(28, comp), Math.max(16, Math.floor(comp / 3)));
      } else if (preset === 'lorenz') {
        const pts = [];
        let x = 0.1, y = 0, z = 0;
        const dt = 0.012, sigma = 10, rho = 28, beta = 8 / 3;
        const steps = Math.min(500, Math.max(180, comp * 4));
        for (let i = 0; i < steps; i++) {
          const dx = sigma * (y - x) * dt;
          const dy = (x * (rho - z) - y) * dt;
          const dz = (x * y - beta * z) * dt;
          x += dx; y += dy; z += dz;
          pts.push(new THREE.Vector3(x, y, z - 25));
        }
        const curve = new THREE.CatmullRomCurve3(pts, false);
        geom = new THREE.TubeGeometry(curve, steps, 2.2, 12, false);
      } else if (preset === 'aizawa') {
        const pts = [];
        let x = 0.1, y = 0, z = 0;
        const a = 0.95, b = 0.7, c = 0.6, d = 3.5, e = 0.25, f = 0.1;
        const dt = 0.014;
        const steps = Math.min(500, Math.max(200, comp * 4));
        for (let i = 0; i < steps; i++) {
          const dx = ((z - b) * x - d * y) * dt;
          const dy = (d * x + (z - b) * y) * dt;
          const dz = (c + a * z - (z * z * z) / 3 - (x * x + y * y) * (1 + e * z) + f * z * (x * x * x)) * dt;
          x += dx; y += dy; z += dz;
          pts.push(new THREE.Vector3(x * 15, y * 15, (z - 0.7) * 15));
        }
        const curve = new THREE.CatmullRomCurve3(pts, false);
        geom = new THREE.TubeGeometry(curve, steps, 2.0, 10, false);
      } else if (preset === 'chua_circuit') {
        const pts = [];
        let x = 0.1, y = 0, z = 0;
        const alpha = 15.6, beta = 28, m0 = -1.143, m1 = -0.714;
        const dt = 0.008;
        const steps = Math.min(500, Math.max(200, comp * 4));
        for (let i = 0; i < steps; i++) {
          const h = m1 * x + 0.5 * (m0 - m1) * (Math.abs(x + 1) - Math.abs(x - 1));
          const dx = alpha * (y - x - h) * dt;
          const dy = (x - y + z) * dt;
          const dz = (-beta * y) * dt;
          x += dx; y += dy; z += dz;
          pts.push(new THREE.Vector3(x * 6.5, y * 6.5, z * 6.5));
        }
        const curve = new THREE.CatmullRomCurve3(pts, false);
        geom = new THREE.TubeGeometry(curve, steps, 2.2, 10, false);
      } else if (preset === 'biomorph') {
        const detail = Math.min(5, Math.max(3, Math.floor(comp / 15)));
        geom = new THREE.IcosahedronGeometry(16, detail);
        const pos = geom.attributes.position;
        const v = new THREE.Vector3();
        for (let i = 0; i < pos.count; i++) {
          v.fromBufferAttribute(pos, i);
          const theta = Math.atan2(v.y, v.x);
          const phi = Math.acos(v.z / v.length());
          const r1 = Math.sin(theta * 3.0) * Math.cos(phi * 2.0) * 5.0;
          const r2 = Math.cos(theta * 5.0 + phi * 3.0) * 3.0;
          const r3 = Math.sin(phi * 6.0) * 2.5;
          v.normalize().multiplyScalar(15 + r1 + r2 + r3);
          pos.setXYZ(i, v.x, v.y, v.z);
        }
      } else if (preset === 'superformula') {
        geom = createSuperformulaGeometry(Math.max(24, Math.floor(comp * 0.75)), Math.max(24, Math.floor(comp * 0.75)));
      } else if (preset === 'bessel_flower') {
        geom = createBesselFlowerGeometry(Math.max(20, Math.floor(comp * 0.5)), Math.max(30, Math.floor(comp * 0.8)));
      } else if (preset === 'coral_reef') {
        const branches = 5;
        const groupGeoms = [];
        const steps = Math.min(80, Math.max(35, Math.floor(comp / 2)));
        for (let b = 0; b < branches; b++) {
          const angle = (b / branches) * Math.PI * 2;
          const pts = [];
          const height = 34;
          for (let s = 0; s <= steps; s++) {
            const t = s / steps;
            const flare = Math.sin(t * Math.PI * 0.5) * 15;
            const px = Math.cos(angle + t * 0.7) * flare;
            const py = (t - 0.5) * height;
            const pz = Math.sin(angle + t * 0.7) * flare;
            const ripple = Math.sin(t * 10 + b) * 1.5;
            pts.push(new THREE.Vector3(px + ripple, py, pz));
          }
          const curve = new THREE.CatmullRomCurve3(pts);
          groupGeoms.push(new THREE.TubeGeometry(curve, steps, 2.4, 8, false));
        }
        groupGeoms.push(new THREE.IcosahedronGeometry(8, 2));
        geom = mergeBufferGeometries(groupGeoms);
      } else if (preset === 'supertorus') {
        geom = new THREE.TorusKnotGeometry(16, 4.5, comp * 3, Math.max(12, Math.floor(comp / 4)), 3, 7);
      } else if (preset === 'trefoil_ring') {
        const pts = [];
        const steps = Math.min(300, Math.max(140, comp * 3));
        for (let i = 0; i <= steps; i++) {
          const t = (i / steps) * Math.PI * 2;
          const x = (Math.sin(t) + 2 * Math.sin(2 * t)) * 8.2;
          const y = (Math.cos(t) - 2 * Math.cos(2 * t)) * 8.2;
          const z = (-Math.sin(3 * t)) * 8.2;
          pts.push(new THREE.Vector3(x, y, z));
        }
        const curve = new THREE.CatmullRomCurve3(pts, true);
        geom = new THREE.TubeGeometry(curve, steps, 3.2, 12, true);
      } else if (preset === 'helix') {
        const totalPts = Math.min(300, Math.max(120, comp * 3));
        const pts = [];
        const turns = 3.5;
        const height = 44;
        const r = 13;
        for (let i = 0; i <= totalPts; i++) {
          const t = i / totalPts;
          const angle = t * Math.PI * 2 * turns;
          const py = (t - 0.5) * height;
          const px = Math.cos(angle) * r;
          const pz = Math.sin(angle) * r;
          pts.push(new THREE.Vector3(px, py, pz));
        }
        const curve = new THREE.CatmullRomCurve3(pts);
        geom = new THREE.TubeGeometry(curve, totalPts, 2.6, 14, false);
      } else if (preset === 'quad_helix') {
        const geoms = [];
        const strands = 4;
        const turns = 2.8;
        const height = 44;
        const steps = Math.min(180, Math.max(80, comp * 2));
        for (let s = 0; s < strands; s++) {
          const phase = (s / strands) * Math.PI * 2;
          const pts = [];
          for (let i = 0; i <= steps; i++) {
            const t = i / steps;
            const angle = t * Math.PI * 2 * turns + phase;
            const r = 13.5;
            pts.push(new THREE.Vector3(Math.cos(angle) * r, (t - 0.5) * height, Math.sin(angle) * r));
          }
          const curve = new THREE.CatmullRomCurve3(pts);
          geoms.push(new THREE.TubeGeometry(curve, steps, 1.8, 8, false));
        }
        const rungs = 7;
        for (let r = 0; r < rungs; r++) {
          const t = (r + 0.5) / rungs;
          const y = (t - 0.5) * height;
          const angle = t * Math.PI * 2 * turns;
          const p1 = new THREE.Vector3(Math.cos(angle) * 13.5, y, Math.sin(angle) * 13.5);
          const p2 = new THREE.Vector3(Math.cos(angle + Math.PI) * 13.5, y, Math.sin(angle + Math.PI) * 13.5);
          const bridgeCurve = new THREE.LineCurve3(p1, p2);
          geoms.push(new THREE.TubeGeometry(bridgeCurve, 8, 1.3, 6, false));
        }
        geom = mergeBufferGeometries(geoms);
      } else if (preset === 'dini_surface') {
        geom = createDiniSurfaceGeometry(Math.max(22, Math.floor(comp * 0.6)), Math.max(26, Math.floor(comp * 0.7)));
      } else if (preset === 'enneper') {
        geom = createEnneperGeometry(Math.max(24, Math.floor(comp * 0.7)), Math.max(24, Math.floor(comp * 0.7)));
      } else if (preset === 'stellated_core') {
        geom = createStellatedCoreGeometry();
      } else {
        geom = new THREE.TorusKnotGeometry(16, 4.5, 96, 24, 2, 3);
      }
      geom.computeBoundingBox();
      geom.center();
      geom.computeVertexNormals();
      if (s !== 1.0) geom.scale(s, s, s);
      return geom;
    }
    const buildFractal = generateFractalGeometry;
`;
  }

  // --- SVG Vector Extrusion to 3D Liquid Chrome ---
  function generateSvgGeometry(svgString, depth, bevelThickness, bevelSize, scale) {
    if (typeof THREE.SVGLoader === 'undefined') {
      console.warn('SVGLoader not loaded, falling back to cyber knot');
      return new THREE.TorusKnotGeometry(16, 5, 128, 32, 2, 3);
    }
    const loader = new THREE.SVGLoader();
    let svgData;
    try {
      svgData = loader.parse(svgString);
    } catch (e) {
      console.error('SVGLoader parse error:', e);
      return new THREE.TorusKnotGeometry(16, 5, 128, 32, 2, 3);
    }

    const paths = svgData.paths || [];
    const shapes = [];
    for (let i = 0; i < paths.length; i++) {
      const pShapes = paths[i].toShapes(true);
      for (let j = 0; j < pShapes.length; j++) {
        shapes.push(pShapes[j]);
      }
    }

    if (shapes.length === 0) {
      return new THREE.TorusKnotGeometry(16, 5, 128, 32, 2, 3);
    }

    const extrudeSettings = {
      depth: parseFloat(depth) || 8,
      bevelEnabled: (parseFloat(bevelThickness) || 0) > 0,
      bevelThickness: parseFloat(bevelThickness) || 1.2,
      bevelSize: parseFloat(bevelSize) || 0.8,
      bevelSegments: 3,
      curveSegments: 12,
      steps: 1
    };

    const geometry = new THREE.ExtrudeGeometry(shapes, extrudeSettings);

    // SVG coordinates have +Y pointing downwards. Rotate 180 deg around X to face upright preserving triangle winding
    geometry.rotateX(Math.PI);

    // Auto-fit to standard studio scene dimensions (~36 units across max dimension)
    geometry.computeBoundingBox();
    const box = geometry.boundingBox;
    const size = new THREE.Vector3();
    box.getSize(size);
    const maxDim = Math.max(size.x, size.y);
    const fitScale = maxDim > 0 ? (36.0 / maxDim) : 1.0;
    geometry.scale(fitScale, fitScale, fitScale);

    const userScale = parseFloat(scale) || 1.0;
    if (userScale !== 1.0) {
      geometry.scale(userScale, userScale, userScale);
    }

    geometry.center();
    geometry.computeVertexNormals();

    return geometry;
  }

  // --- SVG Custom Upload Handlers ---
  function loadSvgFromFile(file) {
    if (!file || !file.name.toLowerCase().endsWith('.svg')) {
      showToast(currentLang === 'fr' ? 'Veuillez sélectionner un fichier .SVG valide' : 'Please select a valid .SVG vector file');
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) => {
      const svgText = e.target.result;
      state.customSvgString = svgText;
      state.customSvgName = file.name;
      state.compose.customSvgString = svgText;
      state.compose.customSvgName = file.name;

      const statusCard = document.getElementById('svg-status-card');
      const statusName = document.getElementById('svg-status-name');
      const statusPaths = document.getElementById('svg-status-paths');
      const pathMatches = svgText.match(/<(path|polygon|rect|circle|ellipse|polyline)/gi);
      const count = pathMatches ? pathMatches.length : 1;
      const pathsLabel = `${count} ${currentLang === 'fr' ? 'tracés vectoriels' : 'vector paths'}`;

      if (statusCard && statusName && statusPaths) {
        statusCard.style.display = 'flex';
        statusName.textContent = file.name;
        statusPaths.textContent = pathsLabel;
      }

      // Also mirror to Compartment 4 Compose status card and select
      const cStatusCard = document.getElementById('compose-svg-status-card');
      const cStatusName = document.getElementById('compose-svg-status-name');
      const cStatusPaths = document.getElementById('compose-svg-status-paths');
      if (cStatusCard && cStatusName && cStatusPaths) {
        cStatusCard.style.display = 'flex';
        cStatusName.textContent = file.name;
        cStatusPaths.textContent = pathsLabel;
      }
      const cSelect = document.getElementById('compose-svg-select');
      if (cSelect) {
        let opt = document.getElementById('compose-svg-custom-option');
        if (!opt) {
          opt = document.createElement('option');
          opt.id = 'compose-svg-custom-option';
          opt.value = 'custom';
          cSelect.insertBefore(opt, cSelect.firstChild);
        }
        opt.textContent = `★ ${file.name}`;
        cSelect.value = 'custom';
      }

      document.querySelectorAll('.svg-preset-btn').forEach(b => b.classList.remove('active'));

      rebuildMesh();
      showToast(currentLang === 'fr' ? 'Logo SVG importé & extrudé en 3D !' : 'SVG Logo imported & extruded in 3D!');
    };
    reader.readAsText(file);
  }

  function resetSvgToDefault() {
    state.customSvgString = null;
    state.customSvgName = '';
    state.svgPreset = 'cyber_falcon';
    const statusCard = document.getElementById('svg-status-card');
    if (statusCard) statusCard.style.display = 'none';
    document.querySelectorAll('.svg-preset-btn').forEach(b => {
      if (b.dataset.svg === 'cyber_falcon') b.classList.add('active');
      else b.classList.remove('active');
    });

    state.compose.customSvgString = null;
    state.compose.customSvgName = '';
    const cStatusCard = document.getElementById('compose-svg-status-card');
    if (cStatusCard) cStatusCard.style.display = 'none';
    const cSelect = document.getElementById('compose-svg-select');
    if (cSelect) {
      const opt = document.getElementById('compose-svg-custom-option');
      if (opt) opt.remove();
      cSelect.value = state.compose.svgPreset || 'cyber_falcon';
    }

    rebuildMesh();
    showToast(currentLang === 'fr' ? 'Logo vectoriel réinitialisé' : 'Vector logo reset to default');
  }

