  function playMechaServoSound() {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      if (!watchAudioCtx) watchAudioCtx = new AudioCtx();
      if (watchAudioCtx.state === 'suspended') watchAudioCtx.resume();
      const t = watchAudioCtx.currentTime;

      const osc = watchAudioCtx.createOscillator();
      const gain = watchAudioCtx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(340, t);
      osc.frequency.exponentialRampToValueAtTime(140, t + 0.11);
      gain.gain.setValueAtTime(0.2, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.13);
      osc.connect(gain);
      gain.connect(watchAudioCtx.destination);
      osc.start(t);
      osc.stop(t + 0.14);
    } catch (e) {}
  }

  function playMechaOverdriveSound() {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      if (!watchAudioCtx) watchAudioCtx = new AudioCtx();
      if (watchAudioCtx.state === 'suspended') watchAudioCtx.resume();
      const t = watchAudioCtx.currentTime;

      const osc = watchAudioCtx.createOscillator();
      const gain = watchAudioCtx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(80, t);
      osc.frequency.exponentialRampToValueAtTime(880, t + 0.65);
      gain.gain.setValueAtTime(0.01, t);
      gain.gain.linearRampToValueAtTime(0.45, t + 0.35);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.85);
      osc.connect(gain);
      gain.connect(watchAudioCtx.destination);
      osc.start(t);
      osc.stop(t + 0.9);

      const sub = watchAudioCtx.createOscillator();
      const subGain = watchAudioCtx.createGain();
      sub.type = 'triangle';
      sub.frequency.setValueAtTime(55, t);
      sub.frequency.linearRampToValueAtTime(38, t + 0.8);
      subGain.gain.setValueAtTime(0.5, t);
      subGain.gain.exponentialRampToValueAtTime(0.001, t + 0.85);
      sub.connect(subGain);
      subGain.connect(watchAudioCtx.destination);
      sub.start(t);
      sub.stop(t + 0.9);
    } catch (e) {}
  }

  function playMechaDeflectSound() {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      if (!watchAudioCtx) watchAudioCtx = new AudioCtx();
      if (watchAudioCtx.state === 'suspended') watchAudioCtx.resume();
      const t = watchAudioCtx.currentTime;

      const osc = watchAudioCtx.createOscillator();
      const gain = watchAudioCtx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(1450, t);
      osc.frequency.exponentialRampToValueAtTime(520, t + 0.28);
      gain.gain.setValueAtTime(0.55, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.32);
      osc.connect(gain);
      gain.connect(watchAudioCtx.destination);
      osc.start(t);
      osc.stop(t + 0.35);
    } catch (e) {}
  }

  function triggerMechaShieldDeflect(hitPoint) {
    if (!activeMechaGroup || !activeMechaGroup.userData) return;
    const uData = activeMechaGroup.userData;
    playMechaDeflectSound();

    if (uData.deflectShield) {
      if (hitPoint) {
        uData.deflectShield.position.copy(activeMechaGroup.worldToLocal(hitPoint.clone()));
      } else {
        uData.deflectShield.position.set(0, 4, 10);
      }
      uData.shieldAnim = {
        active: true,
        startTime: performance.now(),
        duration: 0.55
      };
      uData.deflectShield.visible = true;
    }
  }

  function createMecha3DGroup(isCompose = false) {
    const group = new THREE.Group();
    group.name = 'CyberMecha4D_Root';

    const archetype = isCompose ? (state.compose.mechaArchetype || 'titan') : (state.mechaArchetype || 'titan');
    const finish = isCompose ? (state.compose.mechaFinish || 'cyber_chrome') : (state.mechaFinish || 'cyber_chrome');
    const mats = getMechaMaterials(archetype, finish, isCompose);

    const uData = {
      archetype,
      finish,
      isCompose,
      chestPlates: [],
      pauldrons: [],
      cannons: [],
      wings: null,
      matrixField: null,
      coreMesh: null,
      coreGimbals: [],
      gatlingBarrels: null,
      legs: [],
      floatingRings: [],
      deflectShield: null,
      shieldAnim: { active: false, startTime: 0, duration: 0.55 }
    };

    // Shared Kinetic Deflect Shield Mesh
    const shieldGeo = new THREE.RingGeometry(1, 14, 32);
    const shieldMat = new THREE.MeshBasicMaterial({
      color: 0x00f0ff,
      side: THREE.DoubleSide,
      transparent: true,
      opacity: 0.0,
      blending: THREE.AdditiveBlending
    });
    const deflectShield = new THREE.Mesh(shieldGeo, shieldMat);
    deflectShield.name = 'DeflectShield';
    deflectShield.visible = false;
    deflectShield.userData.isShield = true;
    group.add(deflectShield);
    uData.deflectShield = deflectShield;

    // Ensure active DNA
    if (!state.mechaDna || (archetype !== 'procedural_hybrid' && state.mechaDna.archetype !== archetype)) {
      state.mechaDna = generateMechaDna(archetype);
    }
    const dna = state.mechaDna;

    // Archetype-Specific Builders
    if (archetype === 'titan') {
      buildTitanCenturion(mats, group, uData, dna);
    } else if (archetype === 'valkyrie') {
      buildQuantumValkyrie(mats, group, uData, dna);
    } else if (archetype === 'chrono_colossus') {
      buildChronoColossus(mats, group, uData, dna);
    } else if (archetype === 'arachno_tank') {
      buildArachnoTank(mats, group, uData, dna);
    } else if (archetype === 'seraph_4d') {
      buildSeraphMecha(mats, group, uData, dna);
    } else if (archetype === 'shinobi_void') {
      buildShinobiMecha(mats, group, uData, dna);
    } else if (archetype === 'behemoth_quad') {
      buildBehemothQuadMecha(mats, group, uData, dna);
    } else if (archetype === 'asura_omega') {
      buildAsuraMecha(mats, group, uData, dna);
    } else {
      buildProceduralHybridMecha(mats, group, uData, dna);
    }

    // Tesseract Energy Wings
    const wingsGroup = createTesseractWings(mats);
    group.add(wingsGroup);
    uData.wings = wingsGroup;

    // 4D Stereographic Matrix Field
    const matrixField = create4DMatrixField(mats);
    group.add(matrixField);
    uData.matrixField = matrixField;

    const mechaScale = parseFloat(state.mechaScale) || 1.0;
    group.scale.set(mechaScale, mechaScale, mechaScale);
    group.userData = uData;

    return group;
  }

  // Builder 1: Titan Centurion 4D (Heavy Siege Dreadnought)
  function buildTitanCenturion(mats, root, uData) {
    const torsoGroup = new THREE.Group();
    torsoGroup.name = 'Titan_Torso';

    // Pelvis
    const pelvis = new THREE.Mesh(new THREE.BoxGeometry(10, 6, 8), mats.frameMat);
    pelvis.position.set(0, 0, 0);
    pelvis.name = 'Pelvis';
    torsoGroup.add(pelvis);

    // Spine hydraulic dampers
    const spineL = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.7, 8, 12), mats.accentMat);
    spineL.position.set(-2.8, 5, -1.5);
    spineL.name = 'SpineHydraulic_L';
    torsoGroup.add(spineL);

    const spineR = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.7, 8, 12), mats.accentMat);
    spineR.position.set(2.8, 5, -1.5);
    spineR.name = 'SpineHydraulic_R';
    torsoGroup.add(spineR);

    // Armored Chest Chassis
    const chestCore = new THREE.Mesh(new THREE.BoxGeometry(16, 12, 11), mats.armorMat);
    chestCore.position.set(0, 10, 0);
    chestCore.name = 'Chest_Chassis';
    torsoGroup.add(chestCore);

    // Quantum Singularity Core (Nested in chest)
    const core = new THREE.Mesh(new THREE.SphereGeometry(2.5, 24, 24), mats.coreMat);
    core.position.set(0, 10, 2);
    core.name = 'Quantum_Core';
    core.userData.isCore = true;
    torsoGroup.add(core);
    uData.coreMesh = core;

    const gimbal1 = new THREE.Mesh(new THREE.TorusGeometry(3.6, 0.35, 8, 24), mats.accentMat);
    gimbal1.position.set(0, 10, 2);
    gimbal1.name = 'Core_Gimbal_1';
    torsoGroup.add(gimbal1);

    const gimbal2 = new THREE.Mesh(new THREE.TorusGeometry(4.4, 0.35, 8, 24), mats.accentMat);
    gimbal2.position.set(0, 10, 2);
    gimbal2.rotation.x = Math.PI / 2;
    gimbal2.name = 'Core_Gimbal_2';
    torsoGroup.add(gimbal2);
    uData.coreGimbals.push(gimbal1, gimbal2);

    // 4D Folding Blast Armor Plates (Left & Right)
    const chestLeft = new THREE.Mesh(new THREE.BoxGeometry(7, 10, 2.8), mats.armorMat);
    chestLeft.position.set(-4.2, 10, 5.8);
    chestLeft.name = 'Armor_Chest_L';
    torsoGroup.add(chestLeft);

    const chestRight = new THREE.Mesh(new THREE.BoxGeometry(7, 10, 2.8), mats.armorMat);
    chestRight.position.set(4.2, 10, 5.8);
    chestRight.name = 'Armor_Chest_R';
    torsoGroup.add(chestRight);
    uData.chestPlates.push(chestLeft, chestRight);

    // Head Unit
    const headGroup = new THREE.Group();
    headGroup.name = 'Titan_Head';
    headGroup.position.set(0, 18, 0.5);

    const helmet = new THREE.Mesh(new THREE.BoxGeometry(6, 6.5, 6.5), mats.armorMat);
    helmet.name = 'Helmet';
    headGroup.add(helmet);

    const centurionCrest = new THREE.Mesh(new THREE.BoxGeometry(1.2, 5, 8), mats.accentMat);
    centurionCrest.position.set(0, 4.2, 0);
    centurionCrest.name = 'Centurion_Crest';
    headGroup.add(centurionCrest);

    const visor = new THREE.Mesh(new THREE.BoxGeometry(5.0, 1.2, 1.2), mats.coreMat);
    visor.position.set(0, 0.6, 3.2);
    visor.name = 'Visor_Optic';
    visor.userData.isCore = true;
    headGroup.add(visor);

    torsoGroup.add(headGroup);

    // Arms
    // Left Arm (Heavy Siege Tower Shield)
    const armLGroup = new THREE.Group();
    armLGroup.name = 'Arm_Left';
    armLGroup.position.set(-11, 14, 0);

    const pauldronL = new THREE.Mesh(new THREE.BoxGeometry(8, 7, 9), mats.armorMat);
    pauldronL.name = 'Pauldron_L';
    armLGroup.add(pauldronL);
    uData.pauldrons.push(pauldronL);

    const bicepL = new THREE.Mesh(new THREE.CylinderGeometry(1.5, 1.5, 7, 12), mats.frameMat);
    bicepL.position.set(0, -5, 0);
    bicepL.name = 'Bicep_L';
    armLGroup.add(bicepL);

    const shieldMesh = new THREE.Mesh(new THREE.BoxGeometry(4, 22, 14), mats.armorMat);
    shieldMesh.position.set(-2, -9, 3);
    shieldMesh.name = 'Siege_Shield';
    armLGroup.add(shieldMesh);

    const shieldEmblem = new THREE.Mesh(new THREE.BoxGeometry(0.8, 14, 6), mats.accentMat);
    shieldEmblem.position.set(-4.2, -9, 3);
    shieldEmblem.name = 'Shield_Emblem';
    armLGroup.add(shieldEmblem);

    torsoGroup.add(armLGroup);

    // Right Arm (Quad-Rotary Plasma Cannon)
    const armRGroup = new THREE.Group();
    armRGroup.name = 'Arm_Right';
    armRGroup.position.set(11, 14, 0);

    const pauldronR = new THREE.Mesh(new THREE.BoxGeometry(8, 7, 9), mats.armorMat);
    pauldronR.name = 'Pauldron_R';
    armRGroup.add(pauldronR);
    uData.pauldrons.push(pauldronR);

    const bicepR = new THREE.Mesh(new THREE.CylinderGeometry(1.5, 1.5, 7, 12), mats.frameMat);
    bicepR.position.set(0, -5, 0);
    bicepR.name = 'Bicep_R';
    armRGroup.add(bicepR);

    const cannonHub = new THREE.Mesh(new THREE.CylinderGeometry(2.4, 2.4, 8, 16), mats.frameMat);
    cannonHub.rotation.x = Math.PI / 2;
    cannonHub.position.set(0, -8, 4);
    cannonHub.name = 'Cannon_Hub';
    armRGroup.add(cannonHub);

    const gatlingGroup = new THREE.Group();
    gatlingGroup.name = 'Gatling_Barrels';
    gatlingGroup.position.set(0, -8, 8);

    for (let b = 0; b < 4; b++) {
      const angle = (b / 4) * Math.PI * 2;
      const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.5, 15, 12), mats.accentMat);
      barrel.rotation.x = Math.PI / 2;
      barrel.position.set(Math.cos(angle) * 1.5, Math.sin(angle) * 1.5, 4);
      barrel.name = `Gatling_Barrel_${b + 1}`;
      gatlingGroup.add(barrel);
    }
    armRGroup.add(gatlingGroup);
    uData.gatlingBarrels = gatlingGroup;

    torsoGroup.add(armRGroup);

    // Back Mount: Over-Shoulder Tachyon Railguns
    const railgunL = new THREE.Mesh(new THREE.BoxGeometry(2.5, 3.2, 22), mats.armorMat);
    railgunL.position.set(-6, 17, -8);
    railgunL.name = 'Railgun_L';
    torsoGroup.add(railgunL);

    const railgunR = new THREE.Mesh(new THREE.BoxGeometry(2.5, 3.2, 22), mats.armorMat);
    railgunR.position.set(6, 17, -8);
    railgunR.name = 'Railgun_R';
    torsoGroup.add(railgunR);
    uData.cannons.push(railgunL, railgunR);

    // Legs
    [-4.5, 4.5].forEach((xOffset, idx) => {
      const legGroup = new THREE.Group();
      legGroup.name = `Titan_Leg_${idx === 0 ? 'L' : 'R'}`;
      legGroup.position.set(xOffset, -3, 0);

      const thigh = new THREE.Mesh(new THREE.BoxGeometry(5.5, 11, 6), mats.armorMat);
      thigh.position.set(0, -4, 0);
      thigh.name = `Thigh_${idx}`;
      legGroup.add(thigh);

      const knee = new THREE.Mesh(new THREE.BoxGeometry(5, 5, 4), mats.accentMat);
      knee.position.set(0, -9.5, 1.5);
      knee.name = `Knee_${idx}`;
      legGroup.add(knee);

      const calf = new THREE.Mesh(new THREE.BoxGeometry(6, 13, 7), mats.armorMat);
      calf.position.set(0, -16, -0.5);
      calf.name = `Calf_${idx}`;
      legGroup.add(calf);

      const foot = new THREE.Mesh(new THREE.BoxGeometry(8, 3.5, 13), mats.frameMat);
      foot.position.set(0, -23, 2);
      foot.name = `Foot_${idx}`;
      legGroup.add(foot);

      torsoGroup.add(legGroup);
      uData.legs.push(legGroup);
    });

    root.add(torsoGroup);
    uData.torsoGroup = torsoGroup;
  }

  // Builder 2: Quantum Valkyrie 4D (High-Agility Cyber-Ronin)
  function buildQuantumValkyrie(mats, root, uData) {
    const torsoGroup = new THREE.Group();
    torsoGroup.name = 'Valkyrie_Torso';

    // Pelvis
    const pelvis = new THREE.Mesh(new THREE.BoxGeometry(7, 5, 6), mats.frameMat);
    torsoGroup.add(pelvis);

    // Tapered Chest
    const chestCore = new THREE.Mesh(new THREE.BoxGeometry(12, 10, 8), mats.armorMat);
    chestCore.position.set(0, 8, 0);
    torsoGroup.add(chestCore);

    // Quantum Core
    const core = new THREE.Mesh(new THREE.OctahedronGeometry(2.4, 0), mats.coreMat);
    core.position.set(0, 8, 2.2);
    core.name = 'Quantum_Core';
    core.userData.isCore = true;
    torsoGroup.add(core);
    uData.coreMesh = core;

    // Aerodynamic Folding Chest Flaps
    const chestL = new THREE.Mesh(new THREE.BoxGeometry(5, 8, 2), mats.armorMat);
    chestL.position.set(-3.2, 8, 4.2);
    torsoGroup.add(chestL);

    const chestR = new THREE.Mesh(new THREE.BoxGeometry(5, 8, 2), mats.armorMat);
    chestR.position.set(3.2, 8, 4.2);
    torsoGroup.add(chestR);
    uData.chestPlates.push(chestL, chestR);

    // Valkyrie Head with V-Fin Antennae
    const headGroup = new THREE.Group();
    headGroup.position.set(0, 15, 0.5);

    const helmet = new THREE.Mesh(new THREE.BoxGeometry(4.8, 5.5, 5.5), mats.armorMat);
    headGroup.add(helmet);

    const vFinL = new THREE.Mesh(new THREE.BoxGeometry(1, 8, 0.8), mats.accentMat);
    vFinL.position.set(-3.5, 4, 1);
    vFinL.rotation.z = -Math.PI / 4;
    headGroup.add(vFinL);

    const vFinR = new THREE.Mesh(new THREE.BoxGeometry(1, 8, 0.8), mats.accentMat);
    vFinR.position.set(3.5, 4, 1);
    vFinR.rotation.z = Math.PI / 4;
    headGroup.add(vFinR);

    const visor = new THREE.Mesh(new THREE.BoxGeometry(3.6, 1.0, 1.0), mats.coreMat);
    visor.position.set(0, 0.4, 2.8);
    visor.userData.isCore = true;
    headGroup.add(visor);

    torsoGroup.add(headGroup);

    // Arms with Dual Phase Katanas
    [-8.5, 8.5].forEach((xOffset, idx) => {
      const armGroup = new THREE.Group();
      armGroup.position.set(xOffset, 12, 0);

      const pauldron = new THREE.Mesh(new THREE.BoxGeometry(6, 5, 7), mats.armorMat);
      armGroup.add(pauldron);
      uData.pauldrons.push(pauldron);

      const bicep = new THREE.Mesh(new THREE.CylinderGeometry(1.1, 1.1, 7, 12), mats.frameMat);
      bicep.position.set(0, -5, 0);
      armGroup.add(bicep);

      const forearm = new THREE.Mesh(new THREE.BoxGeometry(3, 8, 3.5), mats.armorMat);
      forearm.position.set(0, -10, 0);
      armGroup.add(forearm);

      // Phase Katana Blade
      const katana = new THREE.Mesh(new THREE.BoxGeometry(0.35, 24, 1.4), mats.coreMat);
      katana.position.set(0, -18, 2.5);
      katana.rotation.x = Math.PI / 12;
      katana.userData.isCore = true;
      katana.name = `Phase_Katana_${idx === 0 ? 'L' : 'R'}`;
      armGroup.add(katana);

      torsoGroup.add(armGroup);
    });

    // Sleek Athletic Legs
    [-3.8, 3.8].forEach((xOffset, idx) => {
      const legGroup = new THREE.Group();
      legGroup.position.set(xOffset, -2, 0);

      const thigh = new THREE.Mesh(new THREE.BoxGeometry(4.2, 11, 4.8), mats.armorMat);
      thigh.position.set(0, -4, 0);
      legGroup.add(thigh);

      const calf = new THREE.Mesh(new THREE.BoxGeometry(4.5, 14, 5.2), mats.armorMat);
      calf.position.set(0, -16, 0);
      legGroup.add(calf);

      const foot = new THREE.Mesh(new THREE.BoxGeometry(4.5, 2.5, 9), mats.accentMat);
      foot.position.set(0, -24, 1.5);
      legGroup.add(foot);

      torsoGroup.add(legGroup);
      uData.legs.push(legGroup);
    });

    root.add(torsoGroup);
    uData.torsoGroup = torsoGroup;
  }

  // Builder 3: Chrono-Colossus 4D (Necron Levitation Relic)
  function buildChronoColossus(mats, root, uData) {
    const colossusGroup = new THREE.Group();
    colossusGroup.name = 'ChronoColossus_Root';

    // Segmented Floating Torso Rings (Levitation Matrix)
    for (let r = 0; r < 3; r++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(8 - r * 1.5, 1.0, 8, 8), mats.armorMat);
      ring.position.set(0, 4 + r * 5, 0);
      ring.rotation.x = Math.PI / 2;
      ring.name = `Levitating_Torso_Ring_${r + 1}`;
      colossusGroup.add(ring);
      uData.floatingRings.push(ring);
    }

    // Singular Chrono-Core (Floating In Center)
    const chronoCore = new THREE.Mesh(new THREE.IcosahedronGeometry(3.2, 1), mats.coreMat);
    chronoCore.position.set(0, 9, 0);
    chronoCore.name = 'Chrono_Singularity_Core';
    chronoCore.userData.isCore = true;
    colossusGroup.add(chronoCore);
    uData.coreMesh = chronoCore;

    // Monolithic Crest Head with Cyclops Eye
    const headGroup = new THREE.Group();
    headGroup.position.set(0, 20, 0);

    const skull = new THREE.Mesh(new THREE.BoxGeometry(6, 7, 7), mats.armorMat);
    headGroup.add(skull);

    const cyclopsEye = new THREE.Mesh(new THREE.SphereGeometry(1.6, 16, 16), mats.coreMat);
    cyclopsEye.position.set(0, 0.5, 3.2);
    cyclopsEye.userData.isCore = true;
    headGroup.add(cyclopsEye);

    colossusGroup.add(headGroup);

    // Floating Arm Segments (Magnetic Suspension)
    [-12, 12].forEach((xOffset, idx) => {
      const armGroup = new THREE.Group();
      armGroup.position.set(xOffset, 12, 0);

      const mantle = new THREE.Mesh(new THREE.TorusGeometry(3.5, 0.8, 8, 8), mats.accentMat);
      mantle.rotation.x = Math.PI / 2;
      armGroup.add(mantle);

      const forearm = new THREE.Mesh(new THREE.BoxGeometry(4, 9, 4), mats.armorMat);
      forearm.position.set(0, -7, 0);
      armGroup.add(forearm);

      // Tachyon Orb hovering below palm
      const orb = new THREE.Mesh(new THREE.SphereGeometry(2.0, 16, 16), mats.coreMat);
      orb.position.set(0, -14, 0);
      orb.userData.isCore = true;
      armGroup.add(orb);

      colossusGroup.add(armGroup);
    });

    // Concentric Ground Grav-Rings (Levitation Base)
    for (let b = 0; b < 3; b++) {
      const baseRing = new THREE.Mesh(new THREE.RingGeometry(5 + b * 4, 6 + b * 4, 32), mats.accentMat);
      baseRing.rotation.x = -Math.PI / 2;
      baseRing.position.set(0, -18 + b * 3, 0);
      baseRing.name = `Ground_Grav_Ring_${b + 1}`;
      colossusGroup.add(baseRing);
      uData.floatingRings.push(baseRing);
    }

    root.add(colossusGroup);
    uData.torsoGroup = colossusGroup;
  }

  // Builder 4: Arachno-Tachyon 4D (Hexapod Heavy Crawler)
  function buildArachnoTank(mats, root, uData) {
    const crawlerGroup = new THREE.Group();
    crawlerGroup.name = 'Arachno_Root';

    // Main Chassis Hull
    const hull = new THREE.Mesh(new THREE.BoxGeometry(18, 7, 18), mats.armorMat);
    hull.position.set(0, 2, 0);
    hull.name = 'Crawler_Hull';
    crawlerGroup.add(hull);

    // Quantum Reactor Core (Rear Hull)
    const core = new THREE.Mesh(new THREE.SphereGeometry(2.8, 20, 20), mats.coreMat);
    core.position.set(0, 3.5, -4);
    core.name = 'Quantum_Core';
    core.userData.isCore = true;
    crawlerGroup.add(core);
    uData.coreMesh = core;

    // 360-degree Top Turret
    const turretGroup = new THREE.Group();
    turretGroup.name = 'Arachno_Turret';
    turretGroup.position.set(0, 7, 2);

    const turretDome = new THREE.Mesh(new THREE.CylinderGeometry(5.5, 6.5, 4.5, 16), mats.armorMat);
    turretGroup.add(turretDome);

    // Twin High-Caliber Tachyon Cannons
    [-2.2, 2.2].forEach(x => {
      const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 0.8, 18, 12), mats.accentMat);
      barrel.rotation.x = Math.PI / 2;
      barrel.position.set(x, 0.8, 9);
      turretGroup.add(barrel);
    });

    crawlerGroup.add(turretGroup);
    uData.cannons.push(turretGroup);

    // 6 Articulated Biomechanical Spider Legs (3 Left, 3 Right)
    const legConfigs = [
      { side: -1, z: 7, idx: 0 },
      { side: -1, z: 0, idx: 1 },
      { side: -1, z: -7, idx: 2 },
      { side: 1, z: 7, idx: 3 },
      { side: 1, z: 0, idx: 4 },
      { side: 1, z: -7, idx: 5 }
    ];

    legConfigs.forEach(cfg => {
      const legRoot = new THREE.Group();
      legRoot.position.set(cfg.side * 9, 2, cfg.z);

      const coxa = new THREE.Mesh(new THREE.BoxGeometry(4, 3, 3), mats.frameMat);
      coxa.position.set(cfg.side * 2, 0, 0);
      legRoot.add(coxa);

      const femur = new THREE.Mesh(new THREE.BoxGeometry(3, 14, 3), mats.armorMat);
      femur.position.set(cfg.side * 7, 6, 0);
      femur.rotation.z = cfg.side * 0.45;
      legRoot.add(femur);

      const tibia = new THREE.Mesh(new THREE.BoxGeometry(2.5, 18, 2.5), mats.accentMat);
      tibia.position.set(cfg.side * 14, -6, 0);
      tibia.rotation.z = -cfg.side * 0.35;
      legRoot.add(tibia);

      crawlerGroup.add(legRoot);
      uData.legs.push({ group: legRoot, side: cfg.side, baseZ: cfg.z, idx: cfg.idx });
    });

    root.add(crawlerGroup);
    uData.torsoGroup = crawlerGroup;
  }

  // --- Modular Mecha Component Builders ---
  function createModularHead(mats, headType) {
    const headGroup = new THREE.Group();
    headGroup.name = 'Modular_Head';

    if (headType === 'v_fin') {
      const helmet = new THREE.Mesh(new THREE.BoxGeometry(4.8, 5.5, 5.5), mats.armorMat);
      helmet.name = 'Helmet_VFin';
      headGroup.add(helmet);
      const vFinL = new THREE.Mesh(new THREE.BoxGeometry(1, 8, 0.8), mats.accentMat);
      vFinL.position.set(-3.5, 4, 1);
      vFinL.rotation.z = -Math.PI / 4;
      vFinL.name = 'Antenna_L';
      headGroup.add(vFinL);
      const vFinR = new THREE.Mesh(new THREE.BoxGeometry(1, 8, 0.8), mats.accentMat);
      vFinR.position.set(3.5, 4, 1);
      vFinR.rotation.z = Math.PI / 4;
      vFinR.name = 'Antenna_R';
      headGroup.add(vFinR);
      const visor = new THREE.Mesh(new THREE.BoxGeometry(3.6, 1.0, 1.0), mats.coreMat);
      visor.position.set(0, 0.4, 2.8);
      visor.name = 'Visor_Optic';
      visor.userData.isCore = true;
      headGroup.add(visor);
    } else if (headType === 'cyclops') {
      const skull = new THREE.Mesh(new THREE.BoxGeometry(6, 6.5, 6.5), mats.armorMat);
      skull.name = 'Helmet_Cyclops';
      headGroup.add(skull);
      const eye = new THREE.Mesh(new THREE.SphereGeometry(1.8, 16, 16), mats.coreMat);
      eye.position.set(0, 0.5, 3.2);
      eye.name = 'Cyclops_Lens';
      eye.userData.isCore = true;
      headGroup.add(eye);
      const brow = new THREE.Mesh(new THREE.BoxGeometry(6.5, 1.5, 2.5), mats.accentMat);
      brow.position.set(0, 2.2, 3.0);
      brow.name = 'Brow_Plate';
      headGroup.add(brow);
    } else if (headType === 'shinobi') {
      const skull = new THREE.Mesh(new THREE.BoxGeometry(5.0, 5.5, 5.5), mats.armorMat);
      skull.name = 'Helmet_Shinobi';
      headGroup.add(skull);
      const hornL = new THREE.Mesh(new THREE.ConeGeometry(0.8, 7, 4), mats.accentMat);
      hornL.position.set(-2.5, 3.8, 0);
      hornL.rotation.z = -0.5;
      hornL.rotation.x = -0.3;
      hornL.name = 'Oni_Horn_L';
      headGroup.add(hornL);
      const hornR = new THREE.Mesh(new THREE.ConeGeometry(0.8, 7, 4), mats.accentMat);
      hornR.position.set(2.5, 3.8, 0);
      hornR.rotation.z = 0.5;
      hornR.rotation.x = -0.3;
      hornR.name = 'Oni_Horn_R';
      headGroup.add(hornR);
      const slit = new THREE.Mesh(new THREE.BoxGeometry(4.2, 0.6, 1.2), mats.coreMat);
      slit.position.set(0, 0.2, 2.8);
      slit.name = 'Shinobi_Slit_Optic';
      slit.userData.isCore = true;
      headGroup.add(slit);
    } else if (headType === 'halo') {
      const skull = new THREE.Mesh(new THREE.BoxGeometry(4.6, 5.8, 5.2), mats.armorMat);
      skull.name = 'Helmet_Halo';
      headGroup.add(skull);
      const halo = new THREE.Mesh(new THREE.TorusGeometry(3.6, 0.35, 8, 32), mats.accentMat);
      halo.position.set(0, 5.5, 0);
      halo.rotation.x = Math.PI / 2;
      halo.name = 'Angelic_Halo';
      headGroup.add(halo);
      const visor = new THREE.Mesh(new THREE.BoxGeometry(3.5, 1.2, 1.2), mats.coreMat);
      visor.position.set(0, 0.4, 2.7);
      visor.name = 'Visor_Optic';
      visor.userData.isCore = true;
      headGroup.add(visor);
    } else if (headType === 'turret') {
      const dome = new THREE.Mesh(new THREE.CylinderGeometry(3.5, 4.2, 4.5, 16), mats.armorMat);
      dome.name = 'Helmet_Turret';
      headGroup.add(dome);
      const dish = new THREE.Mesh(new THREE.CylinderGeometry(2.8, 0.4, 0.8, 16), mats.accentMat);
      dish.position.set(0, 3.2, 0);
      dish.name = 'Radar_Dish';
      headGroup.add(dish);
      const opt = new THREE.Mesh(new THREE.BoxGeometry(2.5, 1.2, 2.2), mats.coreMat);
      opt.position.set(0, 0, 2.8);
      opt.name = 'Sensor_Array';
      opt.userData.isCore = true;
      headGroup.add(opt);
    } else {
      // Centurion Crest (Default)
      const helmet = new THREE.Mesh(new THREE.BoxGeometry(6, 6.5, 6.5), mats.armorMat);
      helmet.name = 'Helmet_Centurion';
      headGroup.add(helmet);
      const crest = new THREE.Mesh(new THREE.BoxGeometry(1.2, 5, 8), mats.accentMat);
      crest.position.set(0, 4.2, 0);
      crest.name = 'Centurion_Crest';
      headGroup.add(crest);
      const visor = new THREE.Mesh(new THREE.BoxGeometry(5.0, 1.2, 1.2), mats.coreMat);
      visor.position.set(0, 0.6, 3.2);
      visor.name = 'Visor_Optic';
      visor.userData.isCore = true;
      headGroup.add(visor);
    }
    return headGroup;
  }

  function createModularShoulder(mats, type, side, uData) {
    const sGroup = new THREE.Group();
    sGroup.name = `Shoulder_${side > 0 ? 'R' : 'L'}`;

    if (type === 'missile_pods') {
      const pod = new THREE.Mesh(new THREE.BoxGeometry(7, 6, 9), mats.armorMat);
      pod.name = `Missile_Pod_${side > 0 ? 'R' : 'L'}`;
      sGroup.add(pod);
      for (let mx = -1.6; mx <= 1.6; mx += 3.2) {
        for (let my = -1.4; my <= 1.4; my += 2.8) {
          const missile = new THREE.Mesh(new THREE.ConeGeometry(0.8, 2.2, 12), mats.accentMat);
          missile.rotation.x = Math.PI / 2;
          missile.position.set(mx, my, 4.8);
          missile.name = 'Missile_Tip';
          sGroup.add(missile);
        }
      }
    } else if (type === 'turbines') {
      const nacelle = new THREE.Mesh(new THREE.CylinderGeometry(3.2, 3.6, 9, 16), mats.armorMat);
      nacelle.rotation.x = Math.PI / 2;
      nacelle.name = `Turbine_${side > 0 ? 'R' : 'L'}`;
      sGroup.add(nacelle);
      const intake = new THREE.Mesh(new THREE.RingGeometry(1.8, 3.0, 16), mats.coreMat);
      intake.position.set(0, 0, 4.6);
      intake.name = 'Turbine_Intake';
      intake.userData.isCore = true;
      sGroup.add(intake);
    } else if (type === 'fins') {
      const slab = new THREE.Mesh(new THREE.BoxGeometry(5.5, 5, 8), mats.armorMat);
      slab.name = `Slab_${side > 0 ? 'R' : 'L'}`;
      sGroup.add(slab);
      const fin = new THREE.Mesh(new THREE.BoxGeometry(0.8, 9, 6), mats.accentMat);
      fin.position.set(side * 3.5, 3.5, 0);
      fin.rotation.z = side * 0.35;
      fin.name = 'Aero_Fin';
      sGroup.add(fin);
    } else if (type === 'mantle') {
      const mantle = new THREE.Mesh(new THREE.BoxGeometry(8, 2.5, 10), mats.armorMat);
      mantle.position.set(side * 1.5, 3.5, 0);
      mantle.rotation.z = side * 0.2;
      mantle.name = 'Stealth_Mantle';
      sGroup.add(mantle);
    } else {
      // Heavy slabs (default)
      const pauldron = new THREE.Mesh(new THREE.BoxGeometry(8, 7, 9), mats.armorMat);
      pauldron.name = `Pauldron_${side > 0 ? 'R' : 'L'}`;
      sGroup.add(pauldron);
    }
    if (uData.pauldrons) uData.pauldrons.push(sGroup);
    return sGroup;
  }

  function createModularRightWeapon(mats, type, uData) {
    const wGroup = new THREE.Group();
    wGroup.name = 'Right_Weapon';

    if (type === 'buster_rifle') {
      const receiver = new THREE.Mesh(new THREE.BoxGeometry(3.5, 5, 12), mats.frameMat);
      receiver.name = 'Buster_Receiver';
      wGroup.add(receiver);
      const barrel = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 1.2, 22, 16), mats.armorMat);
      barrel.rotation.x = Math.PI / 2;
      barrel.position.set(0, 0, 14);
      barrel.name = 'Buster_Barrel';
      wGroup.add(barrel);
      const muzzle = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 1.2, 4, 16), mats.accentMat);
      muzzle.rotation.x = Math.PI / 2;
      muzzle.position.set(0, 0, 26);
      muzzle.name = 'Buster_Muzzle';
      wGroup.add(muzzle);
      const scope = new THREE.Mesh(new THREE.BoxGeometry(1.6, 2.2, 6), mats.coreMat);
      scope.position.set(0, 3.2, 4);
      scope.name = 'Buster_Scope';
      scope.userData.isCore = true;
      wGroup.add(scope);
    } else if (type === 'katana') {
      const hilt = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 0.8, 7, 12), mats.frameMat);
      hilt.rotation.x = Math.PI / 2;
      hilt.name = 'Katana_Hilt';
      wGroup.add(hilt);
      const guard = new THREE.Mesh(new THREE.BoxGeometry(4.2, 4.2, 0.8), mats.accentMat);
      guard.position.set(0, 0, 4);
      guard.name = 'Katana_Guard';
      wGroup.add(guard);
      const blade = new THREE.Mesh(new THREE.BoxGeometry(0.35, 26, 1.8), mats.coreMat);
      blade.position.set(0, -9, 4);
      blade.rotation.x = Math.PI / 12;
      blade.name = 'Katana_Energy_Blade';
      blade.userData.isCore = true;
      wGroup.add(blade);
    } else if (type === 'drill') {
      const hub = new THREE.Mesh(new THREE.CylinderGeometry(3.2, 2.2, 6, 16), mats.frameMat);
      hub.rotation.x = Math.PI / 2;
      hub.name = 'Drill_Chassis';
      wGroup.add(hub);
      const drill = new THREE.Mesh(new THREE.ConeGeometry(3.5, 18, 8), mats.accentMat);
      drill.rotation.x = -Math.PI / 2;
      drill.position.set(0, 0, 11);
      drill.name = 'Drill_Spindle';
      wGroup.add(drill);
      uData.drillMesh = drill;
    } else if (type === 'claws') {
      const bracer = new THREE.Mesh(new THREE.BoxGeometry(3.5, 6, 6), mats.armorMat);
      bracer.name = 'Claw_Bracer';
      wGroup.add(bracer);
      [-1.4, 0, 1.4].forEach((x, cIdx) => {
        const claw = new THREE.Mesh(new THREE.ConeGeometry(0.65, 12, 4), mats.coreMat);
        claw.rotation.x = -Math.PI / 2;
        claw.position.set(x, -1, 8);
        claw.name = `Claw_Talon_${cIdx + 1}`;
        claw.userData.isCore = true;
        wGroup.add(claw);
      });
    } else if (type === 'blasters') {
      [-1.5, 1.5].forEach((x, bIdx) => {
        const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 0.9, 16, 12), mats.accentMat);
        pipe.rotation.x = Math.PI / 2;
        pipe.position.set(x, 0, 7);
        pipe.name = `Blaster_Barrel_${bIdx + 1}`;
        wGroup.add(pipe);
      });
    } else {
      // Quad Gatling (default)
      const hub = new THREE.Mesh(new THREE.CylinderGeometry(2.4, 2.4, 7, 16), mats.frameMat);
      hub.rotation.x = Math.PI / 2;
      hub.name = 'Gatling_Hub';
      wGroup.add(hub);
      const gatlingGroup = new THREE.Group();
      gatlingGroup.name = 'Gatling_Barrels';
      gatlingGroup.position.set(0, 0, 4);
      for (let b = 0; b < 4; b++) {
        const angle = (b / 4) * Math.PI * 2;
        const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.5, 15, 12), mats.accentMat);
        barrel.rotation.x = Math.PI / 2;
        barrel.position.set(Math.cos(angle) * 1.5, Math.sin(angle) * 1.5, 4);
        barrel.name = `Gatling_Barrel_${b + 1}`;
        gatlingGroup.add(barrel);
      }
      wGroup.add(gatlingGroup);
      uData.gatlingBarrels = gatlingGroup;
    }
    return wGroup;
  }

