      const shipBody = new THREE.Group();
      shipBody.name = 'Mothership_Body';
      rootGroup.add(shipBody);

      let mainHullMesh = null;
      let outerRing = null;
      let innerRing = null;
      let singularityCore = null;
      let cornerSlabs = [];
