    function createExportModularBackGear(mats, type, uData) {
      const bGroup = new THREE.Group();
      bGroup.name = 'Back_Gear';

      if (type === 'quad_thrusters') {
        const pack = new THREE.Mesh(new THREE.BoxGeometry(9, 10, 5), mats.frameMat);
        pack.position.set(0, 11, -5);
        bGroup.add(pack);
        [[-3.2, 14], [3.2, 14], [-3.2, 8], [3.2, 8]].forEach(([tx, ty], nIdx) => {
          const noz = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 2.2, 5, 16), mats.armorMat);
          noz.rotation.x = Math.PI / 2;
          noz.position.set(tx, ty, -8);
          bGroup.add(noz);
          const glow = new THREE.Mesh(new THREE.SphereGeometry(1.1, 12, 12), mats.coreMat);
          glow.position.set(tx, ty, -10.5);
          glow.userData.isCore = true;
          bGroup.add(glow);
        });
      } else if (type === 'missile_pack') {
        [-5.5, 5.5].forEach((x, rIdx) => {
          const rack = new THREE.Mesh(new THREE.BoxGeometry(4.5, 8, 7), mats.armorMat);
          rack.position.set(x, 15, -6);
          bGroup.add(rack);
          for (let mx = -1.2; mx <= 1.2; mx += 2.4) {
            for (let my = -2.2; my <= 2.2; my += 2.2) {
              const m = new THREE.Mesh(new THREE.ConeGeometry(0.65, 1.8, 8), mats.accentMat);
              m.rotation.x = Math.PI / 2;
              m.position.set(x + mx, 15 + my, -2.2);
              bGroup.add(m);
            }
          }
        });
      } else if (type === 'railguns') {
        [-6, 6].forEach((x, rgIdx) => {
          const rail = new THREE.Mesh(new THREE.BoxGeometry(2.4, 3.0, 24), mats.armorMat);
          rail.position.set(x, 17, -8);
          bGroup.add(rail);
          if (uData.cannons) uData.cannons.push(rail);
        });
      } else if (type === 'grav_halo') {
        const halo = new THREE.Mesh(new THREE.TorusGeometry(8.5, 0.65, 8, 36), mats.accentMat);
        halo.position.set(0, 12, -7);
        bGroup.add(halo);
        if (uData.floatingRings) uData.floatingRings.push(halo);
      }
      return bGroup;
    }

