  // --- Apply Material Preset ---
  function applyPreset(presetKey) {
    if (!MATERIAL_PRESETS[presetKey]) return;
    const p = MATERIAL_PRESETS[presetKey];
    state.currentPreset = presetKey;
    state.baseColor = p.baseColor;
    state.metalness = p.metalness;
    state.roughness = p.roughness;
    state.clearcoat = p.clearcoat;
    state.clearcoatRoughness = p.clearcoatRoughness;
    state.emissiveColor = p.emissiveColor;
    state.emissiveIntensity = p.emissiveIntensity;

    // Update Form Inputs
    const colorInput = document.getElementById('base-color');
    if (colorInput) colorInput.value = p.baseColor;

    const metalInput = document.getElementById('metalness');
    if (metalInput) {
      metalInput.value = p.metalness;
      document.getElementById('metalness-val').textContent = p.metalness;
    }

    const roughInput = document.getElementById('roughness');
    if (roughInput) {
      roughInput.value = p.roughness;
      document.getElementById('roughness-val').textContent = p.roughness;
    }

    const clearInput = document.getElementById('clearcoat');
    if (clearInput) {
      clearInput.value = p.clearcoat;
      document.getElementById('clearcoat-val').textContent = p.clearcoat;
    }

    const emissiveInput = document.getElementById('emissive-intensity');
    if (emissiveInput) {
      emissiveInput.value = p.emissiveIntensity;
      document.getElementById('emissive-val').textContent = p.emissiveIntensity;
    }

    const emissiveColorInput = document.getElementById('emissive-color');
    if (emissiveColorInput) emissiveColorInput.value = p.emissiveColor;

    state.iridescence = p.iridescence || 0.0;
    state.surfaceDroplets = p.surfaceDroplets || 0.0;

    const iriInput = document.getElementById('iridescence-intensity');
    if (iriInput) {
      iriInput.value = state.iridescence;
      const iriVal = document.getElementById('iridescence-val');
      if (iriVal) iriVal.textContent = state.iridescence.toFixed(2);
    }

    const dropInput = document.getElementById('surface-droplets');
    if (dropInput) {
      dropInput.value = state.surfaceDroplets;
      const dropVal = document.getElementById('droplets-val');
      if (dropVal) dropVal.textContent = state.surfaceDroplets.toFixed(2);
    }

    // Highlight Preset Card
    document.querySelectorAll('.preset-card').forEach(card => {
      if (card.getAttribute('data-preset') === presetKey) {
        card.classList.add('active');
      } else {
        card.classList.remove('active');
      }
    });

    // Update active materials (activeMesh or loaded 3D model)
    updateActiveMaterials(mat => {
      if (mat.color && typeof mat.color.set === 'function') mat.color.set(p.baseColor);
      if ('metalness' in mat && typeof mat.metalness === 'number') mat.metalness = p.metalness;
      if ('roughness' in mat && typeof mat.roughness === 'number') mat.roughness = p.roughness;
      if ('clearcoat' in mat && typeof mat.clearcoat === 'number') mat.clearcoat = p.clearcoat;
      if ('clearcoatRoughness' in mat && typeof mat.clearcoatRoughness === 'number') mat.clearcoatRoughness = p.clearcoatRoughness;
      if (mat.emissive && typeof mat.emissive.set === 'function') mat.emissive.set(p.emissiveColor);
      if ('emissiveIntensity' in mat && typeof mat.emissiveIntensity === 'number') mat.emissiveIntensity = p.emissiveIntensity;

      if (state.surfaceDroplets > 0.01) {
        if (!dropletNormalMap) dropletNormalMap = createProceduralDropletNormalMap();
        mat.normalMap = dropletNormalMap;
        const s = state.surfaceDroplets * 2.5;
        if (mat.normalScale && typeof mat.normalScale.set === 'function') mat.normalScale.set(s, s);
      } else {
        mat.normalMap = null;
      }

      if (mat.userData && mat.userData.shader && mat.userData.shader.uniforms.uIridescence) {
        mat.userData.shader.uniforms.uIridescence.value = state.iridescence;
      } else if (state.iridescence > 0.01) {
        mat.onBeforeCompile = (shader) => {
          shader.uniforms.uIridescence = { value: state.iridescence };
          shader.fragmentShader = 'uniform float uIridescence;\n' + shader.fragmentShader;
          shader.fragmentShader = shader.fragmentShader.replace(
            '#include <dithering_fragment>',
            `#include <dithering_fragment>
            if (uIridescence > 0.01) {
              float viewDot = clamp(dot(normalize(vNormal), normalize(-vViewPosition)), 0.0, 1.0);
              float fres = pow(1.0 - viewDot, 2.2);
              vec3 rainbow = 0.5 + 0.5 * cos(6.28318 * (fres * 1.6 + vec3(0.0, 0.33, 0.67)));
              gl_FragColor.rgb += rainbow * fres * uIridescence * 0.9;
            }`
          );
          mat.userData.shader = shader;
        };
      }
      mat.needsUpdate = true;
    });
  }

