    function handleHeartPhotoUpload(file) {
      if (!file || !file.type.startsWith('image/')) {
        showToast(currentLang === 'fr' ? 'Veuillez sélectionner un fichier image valide' : 'Please select a valid image file');
        return;
      }
      const reader = new FileReader();
      reader.onload = (re) => {
        state.heartPhotoUrl = re.target.result;
        state.heartPhotoName = file.name;
        if (photoThumb) photoThumb.src = state.heartPhotoUrl;
        if (photoFilename) photoFilename.textContent = file.name;
        if (photoPreviewCard) photoPreviewCard.style.display = 'flex';
        if (state.mode === 'heart') rebuildMesh();
        showToast(currentLang === 'fr' ? 'Hologramme photo chargé ! 💖' : 'Memory photo hologram loaded! 💖');
      };
      reader.readAsDataURL(file);
    }

