    const baseColorInput = document.getElementById('base-color');
    if (baseColorInput) {
      baseColorInput.addEventListener('input', (e) => {
        state.baseColor = e.target.value;
        updateActiveMaterials(m => {
          if (m.color && typeof m.color.set === 'function') m.color.set(e.target.value);
        });
      });
    }

    bindSlider('metalness', 'metalness-val', 'metalness', true, (v) => {
      updateActiveMaterials(m => m.metalness = v);
    });

    bindSlider('roughness', 'roughness-val', 'roughness', true, (v) => {
      updateActiveMaterials(m => m.roughness = v);
    });

    bindSlider('clearcoat', 'clearcoat-val', 'clearcoat', true, (v) => {
      updateActiveMaterials(m => m.clearcoat = v);
    });

    bindSlider('emissive-intensity', 'emissive-val', 'emissiveIntensity', true, (v) => {
      updateActiveMaterials(m => m.emissiveIntensity = v);
    });

