    if (emissiveColorInput) {
      emissiveColorInput.addEventListener('input', (e) => {
        state.emissiveColor = e.target.value;
        updateActiveMaterials(m => {
          if (m.emissive && typeof m.emissive.set === 'function') m.emissive.set(e.target.value);
        });
      });
    }

    bindSlider('iridescence-intensity', 'iridescence-val', 'iridescence', true, (v) => {
      updateActiveMaterials(m => {
        if (m.userData && m.userData.shader && m.userData.shader.uniforms.uIridescence) {
          m.userData.shader.uniforms.uIridescence.value = v;
        } else if (v > 0.01) {
          m.onBeforeCompile = (shader) => {
            shader.uniforms.uIridescence = { value: v };
            shader.fragmentShader = 'uniform float uIridescence;\n' + shader.fragmentShader;
            shader.fragmentShader = shader.fragmentShader.replace(
              '#include <dithering_fragment>',
              `#include <dithering_fragment>
              if (uIridescence > 0.01) {
                float viewDot = clamp(dot(normalize(vNormal), normalize(-vViewPosition)), 0.0, 1.0);
                float fres = pow(1.0 - viewDot, 2.2);
                vec3 rainbow = 0.5 + 0.5 * cos(6.28318 * (fres * 1.6 + vec3(0.0, 0.33, 0.67)));
                gl_FragColor.rgb += rainbow * fres * uIridescence * 0.9;
              }`
            );
            m.userData.shader = shader;
          };
          m.needsUpdate = true;
        }
      });
    });

    bindSlider('surface-droplets', 'droplets-val', 'surfaceDroplets', true, (v) => {
      updateActiveMaterials(m => {
        if (v > 0.01) {
          if (!dropletNormalMap) dropletNormalMap = createProceduralDropletNormalMap();
          m.normalMap = dropletNormalMap;
          const s = v * 2.5;
          m.normalScale.set(s, s);
        } else {
          m.normalMap = null;
        }
        m.needsUpdate = true;
      });
    });

